package com.example.leetcodetrainer.adaptive.domain;
import static org.assertj.core.api.Assertions.*;
import java.time.Instant; import java.util.UUID; import org.junit.jupiter.api.Test;
class LearningTaskAttemptTest { @Test void savesDraftAndMakesCompletedContractReadOnly(){var a=new LearningTaskAttempt(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),Instant.now());a.saveContract("returns depth","null -> 0","left/right","1 + max",Instant.now());a.completeFourLineContract(Instant.now());assertThat(a.getStatus()).isEqualTo(LearningTaskAttemptStatus.COMPLETED);assertThat(a.getCompletedAt()).isNotNull();assertThatIllegalStateException().isThrownBy(()->a.saveContract("x","","","",Instant.now()));} @Test void completionIsIdempotent(){var a=new LearningTaskAttempt(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),Instant.now());a.saveContract("one","two","three","four",Instant.now());a.completeFourLineContract(Instant.parse("2026-01-01T00:00:00Z"));var completedAt=a.getCompletedAt();a.completeFourLineContract(Instant.parse("2026-01-02T00:00:00Z"));assertThat(a.getCompletedAt()).isEqualTo(completedAt);} @Test void rejectsIncompleteContractCompletion(){var a=new LearningTaskAttempt(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),Instant.now());a.saveContract("partial","","","",Instant.now());assertThatIllegalStateException().isThrownBy(()->a.completeFourLineContract(Instant.now()));}}
